// ─── File: PriorityNotifyDemo.java ───
// Priority isolation: critical (OTP/security) vs bulk (marketing) on SEPARATE pipelines.
// Each class below would be its own file in a real project.
package com.bank.pn;

import java.util.logging.*;

public class PriorityNotifyDemo {

    private static final Logger log = Logger.getLogger("PN");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        // Two PHYSICALLY SEPARATE pipelines: own topic, own consumers, own rate budget.
        Pipeline critical = new Pipeline("CRITICAL", 4, false);   // steady, reserved, NOT pausable
        Pipeline bulk = new Pipeline("BULK", 50, true);           // elastic, pausable
        NotificationRouter router = new NotificationRouter(critical, bulk);

        // A huge marketing blast floods the BULK pipeline.
        for (int i = 0; i < 1_000_000; i++)
            router.send(new Notification("MKT-" + i, "MARKETING", "PRIYA-and-others", "New scheme!"));

        // Rajesh's OTP enters the CRITICAL pipeline — does NOT sit behind the blast.
        long t0 = System.currentTimeMillis();
        router.send(new Notification("OTP-1", "OTP", "RAJESH", "Your OTP is 448190"));
        router.send(new Notification("SEC-1", "SECURITY", "RAJESH", "New device login"));

        critical.processNext();                                   // picks OTP immediately
        critical.processNext();                                   // picks security alert
        long latency = System.currentTimeMillis() - t0;
        log.info(() -> "CRITICAL OTP latency = " + latency + "ms (bulk backlog=" + bulk.backlog() + " ignored)");

        // During an incident: PAUSE bulk entirely, critical keeps flowing.
        bulk.pause();
        router.send(new Notification("OTP-2", "OTP", "PRIYA", "Your OTP is 771023"));
        critical.processNext();
        log.info(() -> "bulk paused=" + bulk.isPaused() + ", critical still delivering");
    }
}

// ─── model/Notification.java ───
class Notification {
    final String id, type, target, body;
    Notification(String id, String type, String target, String body) {
            this.id = id;
            this.type = type
            this.target = target
            this.body = body;
    }
}

// ─── route/NotificationRouter.java ───  classify at the edge → correct topic
class NotificationRouter {
    private static final Logger log = Logger.getLogger("PN");
    private final Pipeline critical, bulk;
        NotificationRouter(Pipeline critical, Pipeline bulk) { this.critical = critical;
        this.bulk = bulk; }

    void send(Notification n) {
        // classification is part of the contract — bulk can NEVER enter the critical topic
        if (n.type.equals("OTP") || n.type.equals("SECURITY")) critical.enqueue(n);
        else bulk.enqueue(n);
    }
}

// ─── pipeline/Pipeline.java ───  own topic (queue) + own consumer group + own rate budget
class Pipeline {
    private static final Logger log = Logger.getLogger("PN");
    private final String name;
    private final int consumers;           // dedicated consumer group size
    private final boolean pausable;
    private volatile boolean paused = false;
    private final java.util.Queue<Notification> topic = new java.util.concurrent.ConcurrentLinkedQueue<>();

    Pipeline(String name, int consumers, boolean pausable) {
            this.name = name;
            this.consumers = consumers
            this.pausable = pausable;
    }

    void enqueue(Notification n) { topic.add(n); }          // separate topic — no sharing

    void processNext() {                                    // dedicated consumers drain ONLY this topic
        if (paused) { log.warning(() -> name + " paused, skipping"); return; }
        Notification n = topic.poll();
        if (n != null) log.info(() -> name + " delivered " + n.id + " (" + n.type + ") → " + n.target);
    }

        void pause() { if (pausable) { paused = true;
        log.warning(() -> name + " PAUSED (critical unaffected)"); } }
    boolean isPaused() { return paused; }
    int backlog() { return topic.size(); }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
